            String key = entry.getKey();
            V v = entry.getValue();
            if (v == null) continue;
            if (key != null && key.toLowerCase().startsWith("left")){
                left.add(v);
            } else if (key != null && key.toLowerCase().startsWith("right")){
                right.add(v);
            }
        }
        if (left.isEmpty() || right.isEmpty()){
            Collection<V> verts = target.getVertices();
            if (verts == null) return;
            List<V> all = new ArrayList<>(verts);
            int mid = all.size() / 2;
            left.addAll(all.subList(0, mid));
            right.addAll(all.subList(mid, all.size()));
        }
        for (V u : left){
            for (V v : right){
                if (target.getEdge(u, v) == null){
                    target.addEdge(u, v);
                }
            }
        }
    } catch (Exception e){
        // Handle or log exception as needed
    }
}

