public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        if (mappings == null) {
            return null;
        }
        // Retrieve the current mapping for the given table (index)
        Mappings current = getCurrentMapping(tableName);
        if (current == null) {
            // If no current mapping exists, return the input as the diff
            return mappings;
        }
        // Assume Mappings exposes a map of field names to field definitions
        Map<String, Object> currentProps = current.getProperties();
        Map<String, Object> inputProps = mappings.getProperties();
        if (currentProps == null || inputProps == null) {
            return null;
        }
        // Build a new Mappings object containing only fields that are missing in the current mapping
        Mappings diff = new Mappings();
        Map<String, Object> diffProps = new LinkedHashMap<>();
        for (Map.Entry<String, Object> entry : inputProps.entrySet()) {
            String fieldName = entry.getKey();
            // Skip the _source configuration to avoid update conflicts
            if ("_source".equals(fieldName)) {
                continue;
            }
            if (!currentProps.containsKey(fieldName)) {
                diffProps.put(fieldName, entry.getValue());
            }
        }
        diff.setProperties(diffProps);
        return diff;
    } catch (Exception e) {
        // In case of any unexpected error, return null or handle appropriately
        return null;
    }
}

