static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        throw new IllegalArgumentException("timeBucket does not represent a valid date");
    }
    int newDay = 1 + ((day - 1) / dayStep) * dayStep;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0 || index < 0) {
        return 0;
    }
    int end = index + len;
    if (end > str.length()) {
        end = str.length();
    }
    int size = 0;
    int i = index;
    while (i < end) {
        int cp = str.codePointAt(i);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += Character.charCount(cp);
    }
    return size;
}

