private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int count = 0;
    int i = 0;
    final int len = descriptor.length();
    if (descriptor.charAt(0) == '(') {
        // method descriptor: pop argument types
        i++; // skip '('
        while (i < len && descriptor.charAt(i) != ')') {
            // parse a single type
            if (descriptor.charAt(i) == '[') {
                // array type: skip all '['
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                // base type
                if (i < len && descriptor.charAt(i) == 'L') {
                    i++; // skip 'L'
                    while (i < len && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    if (i < len) {
                        i++; // skip ';'
                    }
                } else {
                    // primitive type
                    if (i < len) {
                        i++;
                    }
                }
            } else if (descriptor.charAt(i) == 'L') {
                // object type
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i < len) {
                    i++; // skip ';'
                }
            } else {
                // primitive type
                if (i < len) {
                    i++;
                }
            }
            count++;
        }
    } else {
        // single type descriptor
        if (descriptor.charAt(0) == '[') {
            // array type
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i < len && descriptor.charAt(i) == 'L') {
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i < len) {
                    i++; // skip ';'
                }
            } else {
                if (i < len) {
                    i++; // primitive
                }
            }
        } else if (descriptor.charAt(0) == 'L') {
            // object type
            i++; // skip 'L'
            while (i < len && descriptor.charAt(i) != ';') {
                i++;
            }
            if (i < len) {
                i++; // skip ';'
            }
        } else {
            // primitive type
            if (i < len) {
                i++;
            }
        }
        count = 1;
    }
    // Adjust the stack pointer
    pos -= count;
    if (pos < 0) {
        throw new IllegalStateException("Stack underflow while popping descriptor: " + descriptor);
    }
}

