    }
    int newCapacity = 2 * data.length;
    int required = length + size;
    if (required <= newCapacity) {
        return;
    }
    byte[] newData = new byte[Math.max(newCapacity, required)];
    System.arraycopy(data, 0, newData, 0, length);
    data = newData;
}

