final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    try{
        // locate the start offset of the constant pool entry
        int offset = 8; // skip magic(4), minor(2), major(2)
        int cpCount = ((classFileBuffer[4] & 0xFF) << 8) | (classFileBuffer[5] & 0xFF);
        if(constantPoolEntryIndex < 1 || constantPoolEntryIndex >= cpCount){
            throw new IllegalArgumentException("Invalid constant pool index");
        }
        for(int i=1;i<constantPoolEntryIndex;i++){
            int tag = classFileBuffer[offset] & 0xFF;
            offset++;
            switch(tag){
                case 1: // CONSTANT_Utf8
                    int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset+1] & 0xFF);
                    offset += 2 + len;
                    break;
                case 3: case 4: // CONSTANT_Integer, CONSTANT_Float
                    offset += 4;
                    break;
                case 5: case 6: // CONSTANT_Long, CONSTANT_Double
                    offset += 8;
                    i++; // these take up two entries
                    break;
                case 7: case 8: // CONSTANT_Class, CONSTANT_String
                    offset += 2;
                    break;
                case 9: case 10: case 11: case 12: // Fieldref, Methodref, InterfaceMethodref, NameAndType
                    offset += 4;
                    break;
                case 15: // CONSTANT_MethodHandle
                    offset += 3;
                    break;
                case 16: // CONSTANT_MethodType
                    offset += 2;
                    break;
                case 18: // CONSTANT_InvokeDynamic
                    offset += 4;
                    break;
                default:
                    throw new IllegalArgumentException("Unknown constant pool tag: "+tag);
            }
        }
        int tag = classFileBuffer[offset] & 0xFF;
        if(tag != 1){
            throw new IllegalArgumentException("Entry at index "+constantPoolEntryIndex+" is not a CONSTANT_Utf8");
        }
        int length = ((classFileBuffer[offset+1] & 0xFF) << 8) | (classFileBuffer[offset+2] & 0xFF);
        if(length > charBuffer.length){
