private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new NullPointerException("predicate");
    }
    if (start == null) {
        throw new NullPointerException("start");
    }
    if (stop == null) {
        throw new NullPointerException("stop");
    }
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("dir must be 1 (forward) or -1 (backward)");
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the starting node already satisfies the predicate or is the stop node, return immediately.
    if (predicate.test(circ.getNode()) || circ.getNode().equals(stop)) {
        return circ;
    }

    // Traverse until we hit the stop node or find a node that satisfies the predicate.
    while (true) {
        if (dir > 0) {
            circ.next();
        } else {
            circ.prev();
        }

        Node current = circ.getNode();

        if (current.equals(stop)) {
            return circ;
        }

        if (predicate.test(current)) {
            return circ;
        }

        // Safety check: if we loop back to the starting node, break to avoid infinite loops.
        if (current.equals(start)) {
            return circ;
        }
    }
}

