private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    try {
        ListNodeImpl<E> prev = node.prev;
        ListNodeImpl<E> next = node.next;

        if (prev != null) {
            prev.next = next;
        } else {
            // node was the head
            head = next;
        }

        if (next != null) {
            next.prev = prev;
        } else {
            // node was the tail
            tail = prev;
        }

        // detach the node
        node.prev = null;
        node.next = null;

        // update size
        size--;

        return true;
    } catch (Exception e) {
        // In case of any unexpected error, return false
        return false;
    }
}

