    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    if (name == null) {
        return;
    }
    int len = name.length();
    if (nameStart < 0 || nameStart >= len) {
        return;
    }
    boolean startOfWord = true;
    for (int i = nameStart; i < len; i++) {
        char c = name.charAt(i);
        if (Character.isWhitespace(c)) {
            startOfWord = true;
        } else {
            if (startOfWord) {
                buf.append(c);
                startOfWord = false;
            }
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    try {
        if (typeVariable == null) {
            return Unknown.class;
        }
        Type[] bounds = typeVariable.getBounds();
        if (bounds != null && bounds.length > 0) {
            return bounds[0];
        }
    } catch (Exception e) {
        // ignore and fall through to default
    }
    return Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                if (graph.getEdge(v1, v2) == null) {
                    return false;
                }
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) return bounds;
    for (K key : keys) {
        if (key == null) {
            bounds.add(Integer.MIN_VALUE);
            continue;
        }
        int lower = Integer.MIN_VALUE;
        for (K other : keys) {
            if (other == null) continue;
            int val = other.hashCode();
            if (val <= key.hashCode() && val > lower) {
                lower = val;
            }
        }
        bounds.add(lower);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    java.util.List<Integer> bounds = new java.util.ArrayList<>();
    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
        } else {
            bounds.add(key.hashCode());
        }
    }
    return bounds;
}

