static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    boolean hasNull = false;
    for (Object o : array) {
        if (o == null) {
            hasNull = true;
            break;
        }
    }
    if (!hasNull) {
        if (array instanceof String[]) {
            return (String[]) array;
        } else {
            String[] result = new String[array.length];
            for (int i = 0; i < array.length; i++) {
                result[i] = (String) array[i];
            }
            return result;
        }
    }
    ArrayList<String> list = new ArrayList<>();
    for (Object o : array) {
        if (o != null) {
            list.add((String) o);
        }
    }
    return list.toArray(new String[0]);
}

public static int indexOfExtension(String filename){
    if (filename == null) return -1;
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) return -1;
    int sepIndex = indexOfLastSeparator(filename);
    if (sepIndex > dotIndex) return -1;
    return dotIndex;
}

Edge edgeToNext(){
    Node from = this._currentNode;
    Node to = this._nextNode;
    if (from == null || to == null) {
        return null;
    }
    if (from.isVirtual()) {
        from = from.getRealNode();
    }
    if (to.isVirtual()) {
        to = to.getRealNode();
    }
    for (Edge e : this._edges) {
        if ((e.getFrom() == from && e.getTo() == to) || (e.getFrom() == to && e.getTo() == from)) {
            return e;
        }
    }
    return null;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if(str == null || substring == null){
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if(index < 0 || index > strLen - subLen){
        return false;
    }
    for(int i = 0; i < subLen; i++){
        if(str.charAt(index + i) != substring.charAt(i)){
            return false;
        }
    }
    return true;
}

