public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return new ArrayList<>();
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            // Assume format: timestamp,rest_of_data
            String[] parts = line.split(",", 2);
            if (parts.length < 1) {
                continue;
            }
            long timestamp;
            try {
                timestamp = Long.parseLong(parts[0].trim());
            } catch (NumberFormatException e) {
                continue;
            }
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStart();
                long end = range.getEnd();
                if (timestamp >= start && timestamp <= end) {
                    inRange = true;
                    break;
                }
            }
            if (!inRange) {
                continue;
            }
            ThreadSnapshot snapshot = new ThreadSnapshot();
            // If ThreadSnapshot has setters for timestamp and data, they can be set here
            // snapshot.setTimestamp(timestamp);
            // snapshot.setData(parts.length > 1 ? parts[1] : null);
            result.add(snapshot);
        }
    }
    return result;
}
